package br.com.equilibra.recurrence.domain; import org.junit.jupiter.api.Test;import java.math.BigDecimal;import java.time.LocalDate;import static org.assertj.core.api.Assertions.*;class RecurrenceRuleTest{@Test void createsAndPauses(){RecurrenceRule r=new RecurrenceRule("owner",RecurrenceType.EXPENSE,"Internet",new BigDecimal("129.90"),"category","account",RecurrenceFrequency.MONTHLY,LocalDate.of(2026,10,1),null,31);r.pause();assertThat(r.getStatus()).isEqualTo(RecurrenceStatus.PAUSED);r.resume();assertThat(r.getStatus()).isEqualTo(RecurrenceStatus.ACTIVE);}@Test void rejectsInvalidAmount(){assertThatThrownBy(()->new RecurrenceRule("owner",RecurrenceType.EXPENSE,"x",new BigDecimal("0"),"c","a",RecurrenceFrequency.MONTHLY,LocalDate.now(),null,1)).isInstanceOf(IllegalArgumentException.class);}@Test void preventsInvalidTransition(){RecurrenceRule r=new RecurrenceRule("owner",RecurrenceType.EXPENSE,"x",new BigDecimal("1.00"),"c","a",RecurrenceFrequency.MONTHLY,LocalDate.now(),null,1);r.cancel();assertThatThrownBy(r::resume).isInstanceOf(IllegalStateException.class);}}
